import React, { useState, useEffect } from 'react';

const MortgageCalculator = ({ show, onClose, defaultPrice = 0 }) => {
  const [price, setPrice] = useState(defaultPrice);
  const [downPayment, setDownPayment] = useState(0);
  const [rate, setRate] = useState(10); // 10% interest default
  const [years, setYears] = useState(20);
  const [monthlyPayment, setMonthlyPayment] = useState(0);

  useEffect(() => {
    if (show) {
      setPrice(defaultPrice || 0);
      setDownPayment((defaultPrice || 0) * 0.2); // Default 20% down payment
    }
  }, [show, defaultPrice]);

  useEffect(() => {
    const principal = price - downPayment;
    const monthlyRate = rate / 100 / 12;
    const numberOfPayments = years * 12;

    if (principal > 0 && rate > 0 && years > 0) {
      const x = Math.pow(1 + monthlyRate, numberOfPayments);
      const monthly = (principal * x * monthlyRate) / (x - 1);
      setMonthlyPayment(monthly);
    } else {
      setMonthlyPayment(0);
    }
  }, [price, downPayment, rate, years]);

  if (!show) return null;

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.5)', zIndex: 1060 }}>
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content shadow">
          <div className="modal-header bg-light">
            <h5 className="modal-title">🧮 حاسبة التمويل العقاري</h5>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>
          <div className="modal-body">
            <div className="mb-3">
              <label className="form-label">سعر العقار (جنيه)</label>
              <input type="number" className="form-control" value={price} onChange={e => setPrice(Number(e.target.value))} />
            </div>
            <div className="mb-3">
              <label className="form-label">المقدم (جنيه)</label>
              <input type="number" className="form-control" value={downPayment} onChange={e => setDownPayment(Number(e.target.value))} />
              <small className="text-muted">يتم حساب 20% تلقائياً كحد أدنى مقترح</small>
            </div>
            <div className="row">
              <div className="col-6 mb-3">
                <label className="form-label">الفائدة السنوية (%)</label>
                <input type="number" className="form-control" value={rate} onChange={e => setRate(Number(e.target.value))} />
              </div>
              <div className="col-6 mb-3">
                <label className="form-label">مدة القرض (سنة)</label>
                <input type="number" className="form-control" value={years} onChange={e => setYears(Number(e.target.value))} />
              </div>
            </div>
            
            <div className="alert alert-primary text-center mt-2 mb-0">
              <small className="d-block text-muted mb-1">القسط الشهري التقديري</small>
              <h2 className="fw-bold m-0">{monthlyPayment.toLocaleString(undefined, { maximumFractionDigits: 0 })} جنيه</h2>
            </div>
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onClose}>إغلاق</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MortgageCalculator;
